mapper.select:
SELECT g.group_title, g.group_desc, g.group_thumbnail, gm.is_leader
FROM studygroup g  JOIN group_member gm ON g.group_num = gm.group_num 
WHERE g.group_num = #{group_num} AND gm.member_num = #{member_num}

SELECT group_title, group_desc, group_thumbnail, group_invitecode
FROM studygroup 
WHERE group_num = #{group_num}

SELECT t.tag_num, t.tag_name, t.tag_color 
FROM studytag t JOIN group_tag gt ON t.tag_num = gt.tag_num
WHERE gt.group_num = #{group_num}

mapper.update:
		UPDATE studygroup SET group_title = #{request.group_title}, group_desc = #{request.group_desc}

            , group_thumbnail = #{request.group_thumbnail}

    	WHERE group_num = #{group_num}

mapper.select:
SELECT gm.member_num, m.member_nick, m.member_name, gm.is_leader
FROM group_member gm JOIN member m ON gm.member_num = m.member_num
WHERE gm.group_num = #{group_num}

mapper.delete:
DELETE FROM group_member WHERE group_num = #{group_num} AND member_num = #{target_member_num}
AND is_leader = 0 
AND EXISTS (SELECT 1 FROM group_member gm WHERE gm.group_num = #{group_num}
	AND gm.member_num = #{current_member_num}
	AND gm.is_leader = 1)
